insert into buzzerhood.legacy_network_imports(source_key,source_row,payload,partner_id) select s.source_key,s.source_row,s.payload,p.id from source_rows s join buzzerhood.partners p on p.source_data->>'source'='legacy_html' and (p.source_data->>'source_row')::integer=s.source_row on conflict(source_key) do update set payload=excluded.payload,partner_id=excluded.partner_id;

insert into buzzerhood.partner_platform_accounts(partner_id,platform,handle,is_primary) select partner_id,case when payload->>'platform_category'='Lainnya' then 'Other' else payload->>'platform_category' end,case when payload->>'platform_category'='TikTok' then nullif(payload->>'tt','-') else nullif(payload->>'ig','-') end,true from buzzerhood.legacy_network_imports on conflict(partner_id,platform,handle) do update set is_primary=true,updated_at=now();

insert into buzzerhood.partner_platform_accounts(partner_id,platform,handle,is_primary) select partner_id,'Instagram',nullif(payload->>'ig','-'),false from buzzerhood.legacy_network_imports where nullif(payload->>'ig','-') is not null and payload->>'platform_category'<>'Instagram' on conflict(partner_id,platform,handle) do nothing;
insert into buzzerhood.partner_platform_accounts(partner_id,platform,handle,is_primary) select partner_id,'TikTok',nullif(payload->>'tt','-'),false from buzzerhood.legacy_network_imports where nullif(payload->>'tt','-') is not null and payload->>'platform_category'<>'TikTok' on conflict(partner_id,platform,handle) do nothing;

insert into buzzerhood.partner_audience_metrics(platform_account_id,metric_type,metric_value,observed_at,metric_source,raw_value) select a.id,case when lower(i.payload->>'metric_label') like '%pengunjung%' then 'monthly_visitors'::buzzerhood.metric_type when lower(i.payload->>'metric_label') like '%subscriber%' then 'subscribers'::buzzerhood.metric_type when lower(i.payload->>'metric_label') like '%anggota%' then 'members'::buzzerhood.metric_type when lower(i.payload->>'metric_label') like '%view%' then 'views'::buzzerhood.metric_type else 'followers'::buzzerhood.metric_type end,coalesce((i.payload->>'metric_value')::numeric,0),'2026-09-02T00:00:00Z','legacy_html',jsonb_build_object('source','legacy_html','source_row',i.source_row,'metric_label',i.payload->>'metric_label','total',i.payload->>'total') from buzzerhood.legacy_network_imports i join buzzerhood.partner_platform_accounts a on a.partner_id=i.partner_id and a.is_primary=true where not exists(select 1 from buzzerhood.partner_audience_metrics m where m.platform_account_id=a.id and m.metric_source='legacy_html' and m.raw_value->>'source_row'=i.source_row::text);

insert into buzzerhood.schema_migrations(version,filename) values('0009','0009_legacy_network_import.sql') on conflict(version) do nothing;
